const root = document.getElementById('root');
const state = { me: null, page: 'overview', mobileNav: false, drawer: null, drawerTab: 'overview', searchOpen: false, playbookBuilder: false, connectorTab: 'overview' };
const pages = {
  overview: { label: 'Command center', group: 'Command', icon: '⌁' },
  today: { label: 'Today’s recovery', group: 'Command', icon: '◷' },
  opportunities: { label: 'Opportunities', group: 'Command', icon: '◇' },
  customers: { label: 'Customers', group: 'Customers', icon: '◎' },
  reviews: { label: 'Reviews', group: 'Customers', icon: '✦' },
  inbox: { label: 'Unified inbox', group: 'Customers', icon: '▤' },
  connectors: { label: 'Connector center', group: 'Operations', icon: '↯' },
  automation: { label: 'Automation builder', group: 'Operations', icon: '⤢' },
  agents: { label: 'Agents & traces', group: 'Operations', icon: '✳' },
  analytics: { label: 'Analytics', group: 'Operations', icon: '▥' },
  setup: { label: 'Admin & setup', group: 'Workspace', icon: '⚙' }
};
const groups = ['Command', 'Customers', 'Operations', 'Workspace'];

const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const money = (value) => `$${Number(value || 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}`;
const percent = (value) => `${Math.round(Number(value || 0) * 100)}%`;
const titleize = (value) => String(value || '').replaceAll('_', ' ').replace(/\b\w/g, (m) => m.toUpperCase());
const initials = (email) => String(email || '?').split('@')[0].slice(0, 2).toUpperCase();
const date = (value, withTime = false) => value ? new Date(value).toLocaleString(undefined, withTime ? { dateStyle: 'medium', timeStyle: 'short' } : { dateStyle: 'medium' }) : '—';
const csrf = () => { const part = document.cookie.split(';').map((x) => x.trim()).find((x) => x.startsWith('rros_csrf=')); return part ? decodeURIComponent(part.split('=').slice(1).join('=')) : ''; };

async function api(url, options = {}) {
  const request = { ...options, headers: { ...(options.headers || {}) }, credentials: 'same-origin' };
  if (request.body && typeof request.body !== 'string') { request.headers['Content-Type'] = 'application/json'; request.body = JSON.stringify(request.body); }
  if (request.method && !['GET', 'HEAD'].includes(request.method)) { const token = csrf(); if (token) request.headers['X-CSRF-Token'] = token; }
  const response = await fetch(url, request);
  const payload = await response.json().catch(() => ({}));
  if (!response.ok) {
    const detail = typeof payload.detail === 'object' ? (payload.detail.message || payload.detail.code || JSON.stringify(payload.detail)) : payload.detail;
    throw new Error(detail || `Request failed (${response.status})`);
  }
  return payload;
}

function toast(message, kind = 'normal') {
  const stack = document.querySelector('.toast-stack') || (() => { const node = document.createElement('div'); node.className = 'toast-stack'; document.body.append(node); return node; })();
  const node = document.createElement('div'); node.className = `toast ${kind === 'error' ? 'error' : ''}`; node.textContent = message; stack.append(node);
  setTimeout(() => node.remove(), 3600);
}
function loading(label = 'Loading live workspace data…') { return `<div class="state"><span class="spinner" aria-hidden="true"></span><span>${esc(label)}</span></div>`; }
function empty(title, detail = 'No records are available for this workspace yet.') { return `<div class="state"><strong>${esc(title)}</strong><span>${esc(detail)}</span></div>`; }
function errorState(error, retry = state.page) { return `<div class="state error"><strong>Couldn’t load this view</strong><span>${esc(error.message || error)}</span><button class="btn secondary" data-action="retry" data-page="${esc(retry)}">Try again</button></div>`; }
function pill(value, tone = '') { return `<span class="pill ${tone}">${esc(titleize(value))}</span>`; }
function toneFor(value) { return ['critical', 'high', 'error', 'failed', 'dead_letter'].includes(String(value)) ? 'danger' : ['medium', 'pending', 'awaiting_approval', 'warning'].includes(String(value)) ? 'warn' : ['connected', 'complete', 'completed', 'recovered', 'published', 'active'].includes(String(value)) ? 'good' : ''; }
function pageHead(eyebrow, title, description, actions = '') { return `<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${actions ? `<div class="page-actions">${actions}</div>` : ''}</div>`; }
function stat(label, value, note, delta = '') { return `<div class="card metric-card"><div class="metric-label">${esc(label)}</div><div class="metric-value">${esc(value)}</div>${delta ? `<div class="delta">${esc(delta)}</div>` : ''}<div class="metric-note">${esc(note)}</div></div>`; }
function listState(rows, title, detail) { return rows.length ? `<div class="list">${rows.join('')}</div>` : empty(title, detail); }

function auth(mode = 'signin', message = '') {
  root.innerHTML = `<div class="auth-shell"><div class="card auth-card"><div class="auth-brand"><span class="brand-mark">R</span><strong>Revenue<em>Recovery</em> OS</strong></div><h1>Turn leakage into a measurable operating system.</h1><p class="lead">A governed command center for finding revenue opportunities, coordinating recovery work, and proving what happened.</p><div class="auth-tabs"><button class="${mode === 'signin' ? 'active' : ''}" data-action="auth-mode" data-mode="signin">Sign in</button><button class="${mode === 'signup' ? 'active' : ''}" data-action="auth-mode" data-mode="signup">Create workspace</button></div>${message ? `<div class="notice danger" style="margin-bottom:16px">${esc(message)}</div>` : ''}${mode === 'signin' ? `<form data-form="signin"><div class="field"><label class="field-label" for="auth-org">Organization slug</label><input id="auth-org" name="organization_slug" value="acme-demo" placeholder="acme-demo" autocomplete="organization"></div><div class="field"><label class="field-label" for="auth-email">Email</label><input id="auth-email" name="email" value="owner@example.com" type="email" autocomplete="username" required></div><div class="field"><label class="field-label" for="auth-password">Password</label><input id="auth-password" name="password" value="demo-password" type="password" autocomplete="current-password" required></div><button class="btn primary" style="width:100%" type="submit">Enter command center</button><p class="subtle" style="margin:13px 0 0">Demo access is available when <b>SEED_DEMO=true</b>.</p></form>` : `<form data-form="signup"><div class="field"><label class="field-label" for="auth-name">Company name</label><input id="auth-name" name="organization_name" placeholder="Acme Home Services" required></div><div class="field"><label class="field-label" for="auth-slug">Workspace slug</label><input id="auth-slug" name="organization_slug" placeholder="acme-home-services" required></div><div class="field"><label class="field-label" for="auth-email">Owner email</label><input id="auth-email" name="email" type="email" placeholder="you@company.com" required></div><div class="field"><label class="field-label" for="auth-password">Password</label><input id="auth-password" name="password" type="password" placeholder="Minimum 12 characters" required></div><button class="btn primary" style="width:100%" type="submit">Create workspace</button></form>`}</div></div>`;
}

function shell() {
  root.innerHTML = `<div class="app-shell"><header class="topbar"><button class="btn icon-btn mobile-menu" data-action="toggle-nav" aria-label="Open navigation">☰</button><div class="topbar-brand"><span class="brand-mark">R</span><span>Revenue<em>Recovery</em> OS</span></div><div class="topbar-actions"><button class="btn secondary" data-action="open-search">⌕ <span>Search</span><kbd>⌘ K</kbd></button><div class="workspace-chip">◈ ${esc(state.me.organization_slug || 'workspace')}</div><div class="user-chip"><span class="avatar">${initials(state.me.email)}</span><span>${esc(state.me.email)}</span></div><button class="btn secondary" data-action="logout">Log out</button></div></header><div class="body-layout"><aside class="sidebar" id="sidebar">${groups.map((group) => `<div class="sidebar-section"><div class="sidebar-label">${group}</div>${Object.entries(pages).filter(([, item]) => item.group === group).map(([key, item]) => `<button class="nav-item ${state.page === key ? 'active' : ''}" data-action="navigate" data-page="${key}"><span class="nav-icon">${item.icon}</span>${item.label}</button>`).join('')}</div>`).join('')}<div class="sidebar-bottom"><strong>Safe by default</strong><span class="subtle">Actions stay approval-gated and provider-aware.</span></div></aside><main class="main" id="app">${loading()}</main></div></div><div id="overlay-root"></div>`;
}

async function boot() { try { state.me = await api('/api/me'); shell(); navigate('overview'); } catch (_) { auth(); } }
async function logout() { try { await api('/api/auth/logout', { method: 'POST' }); } catch (_) {} state.me = null; auth(); }
async function navigate(page) { if (!pages[page]) return; state.page = page; state.mobileNav = false; const sidebar = document.getElementById('sidebar'); if (sidebar) sidebar.classList.remove('open'); document.querySelectorAll('.nav-item').forEach((item) => item.classList.toggle('active', item.dataset.page === page)); const app = document.getElementById('app'); if (!app) return; app.innerHTML = loading(); try { await ({ overview, today, opportunities, customers, reviews, inbox, connectors, automation, agents, analytics, setup }[page])(); } catch (error) { app.innerHTML = errorState(error); } }

async function overview() {
  const [dashboard, opportunitiesData, locations, recommendations, onboarding] = await Promise.all([api('/api/dashboard'), api('/api/opportunities?limit=12'), api('/api/analytics/locations'), api('/api/insights/recommendations'), api('/api/onboarding/status').catch(() => null)]);
  const opportunities = Array.isArray(opportunitiesData) ? opportunitiesData : [];
  const leaks = Object.entries(dashboard.leaks || {});
  document.getElementById('app').innerHTML = pageHead('Command center', 'Revenue, with receipts.', 'A live operating view of what is leaking, what is recoverable, and what has been proven.', `<button class="btn secondary" data-action="navigate" data-page="today">Open work queue</button><button class="btn primary" data-action="scan">Run leak scan</button>`) + `<div class="grid">${stat('Actual recovered', money(dashboard.actual_recovered), 'Attributable revenue recorded')} ${stat('Expected opportunity', money(dashboard.expected_value), 'Probability-adjusted leakage')} ${stat('Open opportunities', dashboard.opportunity_count, `${dashboard.urgent || 0} high / critical items`)} ${stat('Directly attributed', money(dashboard.directly_attributed), `Assisted ${money(dashboard.assisted_attributed)} · Influenced ${money(dashboard.influenced_attributed)}`)}</div><div class="grid-2 section"><section class="card pad"><div class="section-header"><div><h2>Priority work</h2><span class="subtle">Ranked by urgency, recoverability, and customer importance.</span></div><button class="btn link" data-action="navigate" data-page="opportunities">View all →</button></div><div class="queue" style="margin-top:14px">${listState(opportunities.slice(0, 6).map(opportunityRow), 'No open opportunities', 'Run a leak scan or ingest operational data to create evidence-backed work.')}</div></section><section class="card pad"><div class="section-header"><div><h2>First-value path</h2><span class="subtle">Make the next setup step explicit.</span></div></div>${onboarding ? `<div class="metric-value" style="margin-top:18px">${esc(onboarding.score)}%</div><div class="progress" style="margin:11px 0 13px"><span style="width:${Math.min(100, Number(onboarding.score || 0))}%"></span></div><p style="margin:0 0 14px">${esc(onboarding.next || 'Review your workspace configuration.')}</p><button class="btn secondary" data-action="navigate" data-page="setup">Open setup checklist</button>` : empty('Setup status unavailable', 'The onboarding endpoint did not return data.')}</section></div><section class="card pad section"><div class="section-header"><div><h2>Leakage map</h2><span class="subtle">Expected value by opportunity type. This is not recovered revenue.</span></div></div>${leaks.length ? `<div class="grid-3" style="margin-top:14px">${leaks.map(([key, value]) => `<div class="list-item"><span class="metric-label">${esc(titleize(key))}</span><strong style="font-size:20px;margin-top:7px">${money(value)}</strong></div>`).join('')}</div>` : empty('No leakage categories yet')}</section><div class="grid-2 section"><section class="card pad"><div class="section-header"><div><h2>Recommended moves</h2><span class="subtle">Rules grounded in recorded workspace signals.</span></div><button class="btn link" data-action="navigate" data-page="agents">Inspect agents →</button></div><div class="queue" style="margin-top:14px">${listState((recommendations || []).map((item) => `<div class="queue-row"><div class="queue-main"><div class="queue-title">${esc(item.title)}</div><div class="queue-meta">${esc(item.reason)}</div></div><span class="pill violet">${money(item.impact)} impact</span></div>`), 'No recommendations', 'The recommendation service has no next action for this workspace.')}</div></section><section class="card pad"><div class="section-header"><div><h2>Location performance</h2><span class="subtle">Expected → recovered</span></div></div><div class="list" style="margin-top:14px">${locations.length ? locations.slice(0, 6).map((item) => `<div><div class="kpi-line"><b>${esc(item.location)}</b><span class="subtle">${money(item.recovered_amount)} recovered</span></div><div class="progress"><span style="width:${item.expected_value ? Math.min(100, item.recovered_amount / item.expected_value * 100) : 0}%"></span></div><div class="subtle" style="margin-top:5px">${money(item.expected_value)} expected · ${item.opportunities} opportunities</div></div>`).join('') : empty('No location data', 'Add location data to compare recovery performance.')}</div></section></div>`;
}
function opportunityRow(item) { return `<div class="queue-row" data-action="open-opportunity" data-id="${esc(item.id)}"><div class="queue-main"><div class="queue-title">${esc(item.reason || 'Untitled opportunity')}</div><div class="queue-meta">${esc(titleize(item.type))} · ${money(item.expected_value)} expected · ${percent(item.confidence)} confidence</div></div><div class="queue-side">${pill(item.severity, toneFor(item.severity))}<span class="subtle">Priority ${Math.round(item.priority_score || 0)}</span></div></div>`; }

async function today() { const rows = await api('/api/recovery/today?limit=50'); document.getElementById('app').innerHTML = pageHead('Command / queue', 'Today’s recovery', 'A focused queue for the work that should happen next. Every action stays inside the audited state machine.', `<button class="btn primary" data-action="scan">Refresh queue</button>`) + `<section class="card"><div class="card-header"><div><h2>${rows.length} active opportunities</h2><span class="subtle">Open an item to investigate, assign, plan, approve, or dismiss.</span></div><span class="pill">Live API data</span></div><div style="padding:14px">${listState(rows.map(opportunityRow), 'Queue is clear', 'No active opportunities are waiting for recovery work.')}</div></section>`; }

async function opportunities() { const rows = await api('/api/opportunities?limit=200'); document.getElementById('app').innerHTML = pageHead('Command / workspace', 'Opportunity workspace', 'Investigate evidence, understand provenance, coordinate recovery, and inspect agent traces without losing the context.', `<button class="btn primary" data-action="scan">Recalculate opportunities</button>`) + `<section class="card"><div class="card-header"><div><h2>${rows.length} opportunities</h2><span class="subtle">Click a row for the full evidence and action workspace.</span></div><span class="pill">${rows.filter((x) => !['recovered', 'dismissed', 'lost', 'expired'].includes(x.status)).length} active</span></div>${rows.length ? `<div class="table-wrap"><table class="table"><thead><tr><th>Opportunity</th><th>Type</th><th>Expected</th><th>Priority</th><th>Confidence</th><th>Status</th></tr></thead><tbody>${rows.map((item) => `<tr class="clickable" data-action="open-opportunity" data-id="${esc(item.id)}"><td><b>${esc(item.reason)}</b><br><span class="subtle">${esc(item.customer_id || 'No customer linked')}</span></td><td>${esc(titleize(item.type))}</td><td><b>${money(item.expected_value)}</b></td><td>${Math.round(item.priority_score || 0)}</td><td>${percent(item.confidence)}</td><td>${pill(item.status, toneFor(item.status))}</td></tr>`).join('')}</tbody></table></div>` : empty('No opportunities yet', 'Run a scan or connect an ingest source before expecting records here.')}</section>`; }

async function openOpportunity(id) { state.drawer = { type: 'opportunity', id }; state.drawerTab = 'overview'; renderDrawer(loading('Loading opportunity evidence…')); try { const [detail, users] = await Promise.all([api(`/api/opportunities/${encodeURIComponent(id)}`), api('/api/users?limit=100').catch(() => [])]); state.drawer.data = { ...detail, users }; renderOpportunityDrawer(); } catch (error) { renderDrawer(errorState(error)); } }
function renderOpportunityDrawer() { const { opportunity: item, events = [], plans = [], actions = [], approvals = [], users = [] } = state.drawer.data; const terminal = ['recovered', 'dismissed', 'lost', 'expired'].includes(item.status); const tab = state.drawerTab; const tabs = ['overview', 'evidence', 'timeline', 'agent trace']; const body = tab === 'overview' ? `<div class="grid-2"><div class="card pad"><div class="metric-label">Estimated value</div><div class="metric-value">${money(item.estimated_value)}</div><div class="metric-note">Expected value ${money(item.expected_value)} · recovered ${money(item.recovered_amount)}</div></div><div class="card pad"><div class="metric-label">Priority signal</div><div class="metric-value">${Math.round(item.priority_score || 0)}</div><div class="metric-note">Urgency ${percent(item.urgency)} · recoverability ${percent(item.recoverability)}</div></div></div><div class="card pad section"><div class="section-header"><h3>Why this matters</h3>${pill(item.status, toneFor(item.status))}</div><p>${esc(item.reason)}</p><div class="notice">Recommended action: ${esc(item.recommended_action || 'No recommendation recorded.')}</div></div><div class="card pad section"><div class="section-header"><h3>Coordinate ownership</h3><span class="subtle">Role permissions are enforced by the API.</span></div><form data-form="assign-opportunity" data-id="${esc(item.id)}"><div class="field"><label class="field-label" for="owner-select">Assigned operator</label><select id="owner-select" name="user_id"><option value="">Unassigned</option>${users.map((user) => `<option value="${esc(user.id)}" ${user.id === item.assigned_user_id ? 'selected' : ''}>${esc(user.email)} · ${esc(user.role)}</option>`).join('')}</select></div><button class="btn secondary" type="submit">Save assignment</button></form></div><div class="card pad section"><div class="section-header"><h3>Recovery controls</h3><span class="subtle">Nothing is sent automatically.</span></div>${terminal ? `<div class="notice">This opportunity is in a terminal state. No recovery mutation is available.</div>` : `<form data-form="recovery-action" data-id="${esc(item.id)}"><div class="field"><label class="field-label">Approved channel</label><select name="channel"><option value="sms">SMS</option><option value="email">Email</option><option value="whatsapp">WhatsApp</option><option value="voice">Voice</option></select></div><div class="field"><label class="field-label">Operator note</label><textarea name="message" placeholder="Add the reason for this approved simulation…">Approved by operator in Revenue Recovery OS.</textarea></div><div class="button-row"><button class="btn secondary" data-action="make-plan" data-id="${esc(item.id)}" type="button">Create plan</button><button class="btn good" type="submit">Approve & simulate</button><button class="btn danger" data-action="dismiss-opportunity" data-id="${esc(item.id)}" type="button">Dismiss</button></div></form>`}</div><div class="card pad section"><div class="section-header"><h3>Recovery brief</h3><button class="btn link" data-action="load-brief" data-id="${esc(item.id)}">Generate from evidence</button></div><div id="brief-box" class="subtle">The brief is generated from the recorded opportunity state; it is not a fabricated summary.</div></div>` : tab === 'evidence' ? `<div class="notice">Provenance is preserved as source references. Attribution language distinguishes observed evidence from causal proof.</div><div class="card pad section"><div class="section-header"><h3>Stored source references</h3><span class="subtle">Detected ${date(item.detected_at || item.created_at, true)}</span></div>${(item.evidence || []).length ? `<div class="list">${item.evidence.map((evidence) => `<div class="list-item"><strong>${esc(evidence.source || 'Source reference')}</strong><span class="subtle">Field: ${esc(evidence.field || '—')} · ${esc(evidence.record_id || 'record not supplied')}</span></div>`).join('')}</div>` : empty('No evidence attached', 'This opportunity has no stored source references to display.')}</div><div class="grid-2 section"><div class="card pad"><div class="metric-label">Attribution status</div><div class="metric-value" style="font-size:22px">${esc(titleize(item.attribution_status || 'pending'))}</div><div class="metric-note">Version ${esc(item.version || '—')} · confidence ${percent(item.confidence)}</div></div><div class="card pad"><div class="metric-label">Customer importance</div><div class="metric-value" style="font-size:22px">${percent(item.customer_importance)}</div><div class="metric-note">A prioritization input, not customer value proof.</div></div></div>` : tab === 'timeline' ? `<div class="card pad"><div class="section-header"><h3>Opportunity timeline</h3><span class="subtle">${events.length} recorded events</span></div>${events.length ? `<div class="list">${events.map((event) => `<div class="list-item"><strong>${esc(titleize(event.type))}</strong><span class="subtle">${date(event.created_at, true)} · ${esc(event.actor || 'system')}</span><pre class="code-block" style="margin-top:9px">${esc(JSON.stringify(event.metadata || {}, null, 2))}</pre></div>`).join('')}</div>` : empty('No timeline events', 'Events will appear when the opportunity changes state.')}</div><div class="grid-2 section"><div class="card pad"><h3>Recovery plans</h3>${plans.length ? plans.map((plan) => `<div class="kpi-line"><span>${esc(plan.channel || 'channel')}</span>${pill(plan.status, toneFor(plan.status))}</div>`).join('') : empty('No recovery plans')}</div><div class="card pad"><h3>Action receipts</h3>${actions.length ? actions.map((action) => `<div class="kpi-line"><span>${esc(action.channel || action.operation || 'action')}</span>${pill(action.status, toneFor(action.status))}</div>`).join('') : empty('No action receipts')}</div></div>` : `<div class="card pad"><div class="section-header"><div><h3>Agent trace</h3><span class="subtle">Run agent reasoning through the governed API boundary.</span></div><button class="btn primary" data-action="run-agents" data-id="${esc(item.id)}">Run agents</button></div><div class="notice warn" style="margin-top:14px">Agent output is advisory. Connector actions still require explicit approval, consent, provider readiness, and audit receipts.</div><div id="agent-trace" class="section">${empty('No trace loaded', 'Run the agent pipeline for this opportunity, or open an existing run from a returned run ID.')}</div></div>`;
  renderDrawer(`<div class="drawer-head"><div><div class="eyebrow">Opportunity workspace</div><h2>${esc(item.reason || 'Opportunity')}</h2><div>${pill(item.type)} ${pill(item.status, toneFor(item.status))}</div></div><button class="btn icon-btn" data-action="close-drawer" aria-label="Close">×</button></div><div class="drawer-body"><div class="tabs">${tabs.map((name) => `<button class="tab ${tab === name ? 'active' : ''}" data-action="drawer-tab" data-tab="${name}">${esc(titleize(name))}</button>`).join('')}</div>${body}</div>`); }

function renderDrawer(content) { const target = document.getElementById('overlay-root'); if (!target) return; target.innerHTML = `<div class="overlay" data-action="close-drawer"></div><aside class="drawer">${content}</aside>`; }
async function refreshOpportunity() { if (state.drawer?.type === 'opportunity') await openOpportunity(state.drawer.id); }

async function customers() { const rows = await api('/api/customers?limit=200'); document.getElementById('app').innerHTML = pageHead('Customers / 360', 'Customer 360', 'Move from a name to a complete, consent-aware view of value, health, communications, and recovery history.', `<div class="field" style="margin:0;min-width:220px"><input id="customer-search" placeholder="Search customers…" data-action="customer-search"></div>`) + `<section class="card"><div class="card-header"><div><h2>${rows.length} customers</h2><span class="subtle">Select a customer to open the 360 workspace.</span></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Customer</th><th>Contact</th><th>Lifecycle</th><th>Record ID</th></tr></thead><tbody>${rows.length ? rows.map((item) => `<tr class="clickable" data-action="open-customer" data-id="${esc(item.id)}"><td><b>${esc(item.name)}</b></td><td>${esc(item.email || item.phone || '—')}</td><td>${pill(item.lifecycle_status, toneFor(item.lifecycle_status))}</td><td><span class="subtle">${esc(item.id)}</span></td></tr>`).join('') : `<tr><td colspan="4">${empty('No customers found', 'Customer records will appear after ingestion.')}</td></tr>`}</tbody></table></div></section>`; }
async function openCustomer(id) { state.drawer = { type: 'customer', id }; state.drawerTab = 'overview'; renderDrawer(loading('Loading customer 360…')); try { state.drawer.data = await api(`/api/customers/${encodeURIComponent(id)}`); renderCustomerDrawer(); } catch (error) { renderDrawer(errorState(error)); } }
function renderCustomerDrawer() { const data = state.drawer.data; const customer = data.customer; const tab = state.drawerTab; const body = tab === 'overview' ? `<div class="grid-2"><div class="card pad"><div class="metric-label">Lifetime value</div><div class="metric-value">${money(data.lifetime_value)}</div><div class="metric-note">Paid transactions recorded</div></div><div class="card pad"><div class="metric-label">Behavioral risk</div><div class="metric-value">${esc(data.health.risk_score)}/100</div><div class="metric-note">${esc(data.health.risk_level)} · observed signal, not causal proof</div></div></div><div class="card pad section"><div class="section-header"><h3>Profile</h3>${pill(customer.lifecycle_status)}</div><p style="font-size:16px;margin-bottom:4px"><b>${esc(customer.name)}</b></p><p class="subtle">${esc(customer.email || 'No email')} · ${esc(customer.phone || 'No phone')}</p></div><div class="card pad section"><div class="section-header"><h3>Health factors</h3><span class="subtle">${data.health.factors.length} observed</span></div>${data.health.factors.length ? `<div class="list">${data.health.factors.map((factor) => `<div class="list-item"><strong>${esc(titleize(factor.factor))} · +${esc(factor.impact)} points</strong><span class="subtle">${esc(factor.detail)}</span></div>`).join('')}</div>` : empty('No elevated risk factors', 'The API returned no observed health factors for this customer.')}</div><div class="grid-2 section"><div class="card pad"><h3>Open opportunities</h3>${data.opportunities.length ? data.opportunities.slice(0, 5).map((item) => `<div class="kpi-line"><span>${esc(item.reason)}</span><b>${money(item.expected_value)}</b></div>`).join('') : empty('No linked opportunities')}</div><div class="card pad"><h3>Consent status</h3>${data.consents.length ? data.consents.map((consent) => `<div class="kpi-line"><span>${esc(titleize(consent.channel))}</span>${pill(consent.allowed ? 'allowed' : 'blocked', consent.allowed ? 'good' : 'danger')}</div>`).join('') : empty('No consent records', 'No channel consent was returned for this customer.')}</div></div>` : tab === 'timeline' ? `<div class="card pad"><div class="section-header"><h3>Revenue timeline</h3><span class="subtle">${data.transactions.length} transactions · ${data.invoices.length} invoices</span></div><div class="list">${data.transactions.slice(0, 12).map((item) => `<div class="list-item"><strong>${money(item.amount)} · ${esc(item.status)}</strong><span class="subtle">${date(item.paid_at, true)}</span></div>`).join('') || empty('No transactions recorded')}</div></div><div class="card pad section"><h3>Communications</h3><div class="list">${data.messages.slice(0, 8).map((item) => `<div class="list-item"><strong>${esc(titleize(item.channel))} · ${esc(item.direction)}</strong><span class="subtle">${date(item.occurred_at, true)}${item.body_preview ? ` · ${esc(item.body_preview)}` : ''}</span></div>`).join('') || empty('No messages recorded')}${data.calls.slice(0, 8).map((item) => `<div class="list-item"><strong>Call · ${esc(item.direction)}</strong><span class="subtle">${date(item.started_at, true)} · ${esc(item.status)}</span></div>`).join('')}</div></div>` : `<div class="grid-2"><div class="card pad"><h3>Reviews</h3>${data.reviews.length ? data.reviews.map((item) => `<div class="kpi-line"><span>${esc(item.source)} · ${esc(item.topic || 'general')}</span>${pill(`${item.rating}/5`, item.rating <= 2 ? 'danger' : item.rating === 3 ? 'warn' : 'good')}</div>`).join('') : empty('No reviews recorded')}</div><div class="card pad"><h3>Financial friction</h3>${data.payments.length ? data.payments.map((item) => `<div class="kpi-line"><span>${esc(item.failure_code || 'payment')} · ${esc(item.status)}</span><b>${money(item.amount)}</b></div>`).join('') : empty('No payment events recorded')}</div></div>`; renderDrawer(`<div class="drawer-head"><div><div class="eyebrow">Customer 360</div><h2>${esc(customer.name)}</h2><span class="subtle">${esc(customer.email || customer.phone || 'No contact details')}</span></div><button class="btn icon-btn" data-action="close-drawer">×</button></div><div class="drawer-body"><div class="tabs"><button class="tab ${tab === 'overview' ? 'active' : ''}" data-action="drawer-tab" data-tab="overview">Overview</button><button class="tab ${tab === 'timeline' ? 'active' : ''}" data-action="drawer-tab" data-tab="timeline">Revenue & activity</button><button class="tab ${tab === 'signals' ? 'active' : ''}" data-action="drawer-tab" data-tab="signals">Signals</button></div>${body}</div>`); }

async function reviews() { const rows = await api('/api/reviews?limit=200'); document.getElementById('app').innerHTML = pageHead('Customers / feedback', 'Reviews intelligence', 'Keep review context close to the customer record, with drafts clearly separated from approved or sent states.') + `<section class="card"><div class="card-header"><div><h2>${rows.length} reviews</h2><span class="subtle">Drafting never sends a public response.</span></div></div>${rows.length ? `<div class="table-wrap"><table class="table"><thead><tr><th>Rating</th><th>Review</th><th>Customer</th><th>Response</th></tr></thead><tbody>${rows.map((item) => `<tr><td>${pill(`${item.rating}/5`, item.rating <= 2 ? 'danger' : item.rating === 3 ? 'warn' : 'good')}</td><td><b>${esc(item.topic || 'General')}</b><br><span class="subtle">${esc(item.text || '')}</span></td><td>${item.customer_id ? `<button class="btn link" data-action="open-customer" data-id="${esc(item.customer_id)}">${esc(item.customer_id)}</button>` : '<span class="subtle">Unmatched</span>'}</td><td><div>${pill(item.response_status || 'not drafted', toneFor(item.response_status))}</div><button class="btn secondary" style="margin-top:7px" data-action="draft-review" data-id="${esc(item.id)}">Open draft</button></td></tr>`).join('')}</tbody></table></div>` : empty('No reviews found', 'Review records will appear after ingestion.')}</section>`; }
async function openReviewDraft(id) { state.drawer = { type: 'review', id }; renderDrawer(loading('Loading response draft…')); try { const data = await api(`/api/reviews/${encodeURIComponent(id)}/response-draft`); renderDrawer(`<div class="drawer-head"><div><div class="eyebrow">Review workflow</div><h2>Human-approved response</h2><span class="subtle">The API controls drafting and approval; live sending requires a provider adapter.</span></div><button class="btn icon-btn" data-action="close-drawer">×</button></div><div class="drawer-body"><div class="notice warn">This surface does not send public responses. Save a draft, then explicitly approve it if your role permits.</div><form data-form="review-draft" data-id="${esc(id)}" class="section"><div class="field"><label class="field-label" for="review-text">Response draft</label><textarea id="review-text" name="draft_text" style="min-height:230px">${esc(data.draft?.text || '')}</textarea></div><div class="button-row"><button class="btn primary" type="submit">Save draft</button><button class="btn good" data-action="approve-review" data-id="${esc(id)}" type="button">Approve draft</button></div></form></div>`); } catch (error) { renderDrawer(errorState(error)); } }

async function inbox() { const rows = await api('/api/inbox?limit=500'); const needs = rows.filter((row) => row.needs_response); document.getElementById('app').innerHTML = pageHead('Customers / conversations', 'Unified inbox', 'A response queue across recorded channels. Nothing is auto-sent from this screen.') + `<div class="grid">${stat('Open threads', rows.length, 'Latest known conversations')}${stat('Needs response', needs.length, 'Inbound activity newer than outbound')}${stat('Oldest gap', needs.length ? `${Math.max(...needs.map((row) => row.age_hours)).toFixed(1)}h` : '0h', 'Based on recorded event time')}${stat('Channels', new Set(rows.map((row) => row.channel)).size, 'Channels represented in source data')}</div><section class="card section"><div class="card-header"><div><h2>Response queue</h2><span class="subtle">Prioritized by unanswered inbound activity.</span></div></div><div style="padding:14px">${listState(rows.map((row) => `<div class="queue-row"><div class="queue-main"><div class="queue-title">${esc(row.subject || row.customer_id || row.lead_id || 'Conversation')}</div><div class="queue-meta">${esc(row.channel)} · ${esc(row.last_direction)} · ${date(row.last_at, true)} · ${esc(row.age_hours)}h ago</div><div class="subtle" style="margin-top:5px">${esc(row.body_preview || 'No message preview')}</div></div><div class="queue-side">${pill(row.needs_response ? 'needs response' : 'up to date', row.needs_response ? 'warn' : 'good')}</div></div>`), 'No communication events', 'No inbox threads have been ingested for this workspace.')}</div></section>`; }

async function connectors() { const [catalog, configured, runtime] = await Promise.all([api('/api/integrations/catalog'), api('/api/integrations'), api('/api/runtime/connectors').catch(() => null)]); const rows = Object.fromEntries(configured.map((item) => [item.provider, item])); document.getElementById('app').innerHTML = pageHead('Operations / runtime', 'Connector center', 'See the difference between a provider in the catalog, a configured connection, and a verified live adapter.', `<button class="btn secondary" data-action="runtime-refresh">Refresh runtime</button>`) + `<div class="grid">${stat('Catalog providers', catalog.providers.length, 'Available connection definitions')}${stat('Configured', configured.filter((item) => !['not_configured', 'disconnected'].includes(item.status)).length, 'Tenant credentials stored')}${stat('Live adapters', runtime?.count ?? '—', runtime ? 'Runtime registry count' : 'Runtime status unavailable')}${stat('Verified', configured.filter((item) => item.status === 'connected').length, 'Connections reporting connected')}</div><section class="card section"><div class="card-header"><div><h2>Provider catalog</h2><span class="subtle">Select a connector to inspect capabilities and readiness.</span></div><span class="pill">Credentials encrypted server-side</span></div><div class="grid-3" style="padding:14px">${catalog.providers.map((provider) => connectorCard(provider, rows[provider.provider], runtime?.connectors?.find((item) => item.provider === provider.provider))).join('')}</div></section>`; }
function connectorCard(provider, configured = {}, runtime = {}) { const status = configured.status || 'not_configured'; return `<button class="card pad" style="text-align:left;cursor:pointer" data-action="open-connector" data-id="${esc(provider.provider)}"><div class="section-header"><div><h3>${esc(provider.name)}</h3><span class="subtle">${esc(provider.category)}</span></div>${pill(status, toneFor(status))}</div><p class="subtle" style="min-height:42px">${esc((provider.capabilities || []).slice(0, 4).join(' · ') || 'Capability metadata unavailable')}</p><div class="kpi-line"><span>Auth</span><b>${esc(provider.auth || 'account setup')}</b></div><div class="kpi-line"><span>Adapter</span><b>${runtime.adapter_ready ? 'ready' : provider.implementation || 'catalog only'}</b></div></button>`; }
async function openConnector(providerKey) { state.drawer = { type: 'connector', id: providerKey }; state.connectorTab = 'overview'; renderDrawer(loading('Loading connector detail…')); try { const [catalog, configured, runtime] = await Promise.all([api('/api/integrations/catalog'), api('/api/integrations'), api('/api/runtime/connectors').catch(() => null)]); const provider = catalog.providers.find((item) => item.provider === providerKey); state.drawer.data = { provider, configured: configured.find((item) => item.provider === providerKey) || {}, runtime: runtime?.connectors?.find((item) => item.provider === providerKey) || {} }; renderConnectorDrawer(); } catch (error) { renderDrawer(errorState(error)); } }
function renderConnectorDrawer() { const { provider, configured, runtime } = state.drawer.data; const tab = state.connectorTab; const capabilities = (provider.capabilities || []).map((capability) => `<div class="list-item"><strong>${esc(titleize(capability))}</strong><span class="subtle">Advertised in provider catalog; operational availability depends on adapter readiness.</span></div>`).join(''); const body = tab === 'overview' ? `<div class="grid-2"><div class="card pad"><div class="metric-label">Connection state</div><div class="metric-value" style="font-size:23px">${esc(titleize(configured.status || 'not configured'))}</div><div class="metric-note">Last health check ${date(configured.health_checked_at, true)}</div></div><div class="card pad"><div class="metric-label">Runtime readiness</div><div class="metric-value" style="font-size:23px">${runtime.adapter_ready ? 'Ready' : 'Unavailable'}</div><div class="metric-note">${runtime.adapter ? esc(runtime.adapter) : 'No installed live adapter reported'}</div></div></div><div class="notice ${runtime.adapter_ready ? '' : 'warn'} section">${runtime.adapter_ready ? 'The runtime reports an installed adapter. Test the tenant connection before relying on sync or outbound actions.' : 'This catalog entry does not report an installed live adapter. RROS will not pretend that a live sync or send is available.'}</div><div class="card pad section"><h3>Connection metadata</h3><div class="kpi-line"><span>Auth mode</span><b>${esc(provider.auth || 'account-specific')}</b></div><div class="kpi-line"><span>Implementation</span><b>${esc(provider.implementation || 'registry only')}</b></div><div class="kpi-line"><span>Last sync</span><b>${date(configured.last_sync_at, true)}</b></div>${configured.last_error ? `<div class="notice danger" style="margin-top:13px">${esc(configured.last_error)}</div>` : ''}</div>` : tab === 'capabilities' ? `<div class="card pad"><div class="section-header"><h3>Catalog capabilities</h3><span class="subtle">${(provider.capabilities || []).length} declared</span></div><div class="list section">${capabilities || empty('No capability metadata', 'The provider catalog returned no capabilities.')}</div></div><div class="card pad section"><h3>Sync resources</h3><div class="list section">${(runtime.sync_resources || runtime.catalog_resources || []).length ? (runtime.sync_resources || runtime.catalog_resources).map((resource) => `<div class="kpi-line"><span>${esc(titleize(resource))}</span>${pill(runtime.sync_resources?.includes(resource) ? 'adapter ready' : 'catalog only', runtime.sync_resources?.includes(resource) ? 'good' : 'warn')}</div>`).join('') : empty('No sync resources reported')}</div></div>` : `<div class="card pad"><div class="section-header"><div><h3>Configure securely</h3><span class="subtle">Secrets are sent only to the existing API route and are not rendered back.</span></div></div>${provider.auth === 'oauth' ? `<div class="notice">OAuth is required for this provider. Start the existing OAuth flow; if its client is not configured, the API will return an explicit unavailable state.</div><button class="btn primary" style="margin-top:14px" data-action="oauth-connect" data-id="${esc(provider.provider)}">Start OAuth</button>` : `<form data-form="connector-config" data-id="${esc(provider.provider)}" class="section"><div class="field"><label class="field-label">Credential key</label><input name="credential_key" placeholder="api_key, access_token, or token" required></div><div class="field"><label class="field-label">Credential value</label><input name="credential_value" type="password" autocomplete="off" required></div><button class="btn primary" type="submit">Store encrypted credential</button></form>`}</div><div class="card pad section"><div class="section-header"><h3>Connection actions</h3><span class="subtle">These call existing provider routes.</span></div><div class="button-row"><button class="btn secondary" data-action="test-connector" data-id="${esc(provider.provider)}">Test connection</button>${configured.status && configured.status !== 'not_configured' ? `<button class="btn danger" data-action="disconnect-connector" data-id="${esc(provider.provider)}">Disconnect</button>` : ''}</div></div>`; renderDrawer(`<div class="drawer-head"><div><div class="eyebrow">Connector detail</div><h2>${esc(provider.name)}</h2><span class="subtle">${esc(provider.provider)} · ${esc(provider.category)}</span></div><button class="btn icon-btn" data-action="close-drawer">×</button></div><div class="drawer-body"><div class="tabs"><button class="tab ${tab === 'overview' ? 'active' : ''}" data-action="connector-tab" data-tab="overview">Overview</button><button class="tab ${tab === 'capabilities' ? 'active' : ''}" data-action="connector-tab" data-tab="capabilities">Capabilities</button><button class="tab ${tab === 'configure' ? 'active' : ''}" data-action="connector-tab" data-tab="configure">Configure</button></div>${body}</div>`); }

async function automation() { const rows = await api('/api/playbooks'); document.getElementById('app').innerHTML = pageHead('Operations / automation', 'Automation builder', 'Compose reusable, approval-gated playbooks from real opportunity conditions. Publishing never authorizes live sending.', `<button class="btn primary" data-action="toggle-builder">${state.playbookBuilder ? 'Close builder' : 'New automation'}</button>`) + (state.playbookBuilder ? playbookForm() : '') + `<section class="grid-3 section">${rows.length ? rows.map((item) => `<article class="card pad"><div class="section-header"><h3>${esc(item.name)}</h3>${pill(item.status, toneFor(item.status))}</div><p class="subtle">${esc(item.description || 'No description')}</p><div class="kpi-line"><span>Trigger</span><b>${esc(item.trigger_type)}</b></div><div class="kpi-line"><span>Steps</span><b>${item.steps.length} · v${item.version}</b></div><div class="button-row" style="margin-top:14px">${item.status === 'draft' ? `<button class="btn primary" data-action="publish-playbook" data-id="${esc(item.id)}">Publish</button>` : ''}<button class="btn secondary" data-action="apply-playbook" data-id="${esc(item.id)}">Apply to opportunity</button></div></article>`).join('') : `<div class="card" style="grid-column:1/-1">${empty('No automations yet', 'Use the builder to create the first draft from explicit conditions and steps.')}</div>`}</section>`; }
function playbookForm() { return `<section class="card pad section"><div class="section-header"><div><h2>Build an automation</h2><span class="subtle">This creates a draft through <code>/api/playbooks</code>. No sample record is inserted.</span></div></div><form data-form="playbook" class="section"><div class="grid-2"><div class="field"><label class="field-label">Name</label><input name="name" placeholder="Stalled lead recovery" required></div><div class="field"><label class="field-label">Trigger type</label><input name="trigger_type" value="opportunity.created" required></div></div><div class="field"><label class="field-label">Description</label><textarea name="description" placeholder="Describe the operating intent…"></textarea></div><div class="grid-2"><div class="field"><label class="field-label">Opportunity types</label><input name="types" placeholder="lost_lead, quote_decay"></div><div class="field"><label class="field-label">Recovery channel</label><select name="channel"><option value="sms">SMS</option><option value="email">Email</option><option value="whatsapp">WhatsApp</option><option value="voice">Voice</option></select></div></div><div class="notice warn">Every generated plan remains approval-gated. Provider readiness and channel consent are evaluated later by the API.</div><button class="btn primary" type="submit" style="margin-top:14px">Create draft automation</button></form></section>`; }

async function agents() { const [catalog, learning] = await Promise.all([api('/api/agents'), api('/api/agent-learning').catch(() => null)]); document.getElementById('app').innerHTML = pageHead('Operations / intelligence', 'Agents & traces', 'Inspect the registered agent system and its learning signals. Runs are attached to opportunities so every trace has business context.', `<button class="btn secondary" data-action="navigate" data-page="opportunities">Open opportunity workspace</button>`) + `<div class="grid">${stat('Registered agents', catalog.length, 'Definitions returned by the runtime')}${stat('Learning samples', learning?.sample_size ?? '—', learning ? 'Recorded outcomes' : 'Unavailable for this role')}${stat('Feedback streams', learning ? Object.keys(learning.agent_feedback || {}).length : '—', learning ? 'Agents with recorded ratings' : 'Not available')}${stat('Policy', 'Advisory', 'Model or policy changes require versioned deployment')}</div><section class="card section"><div class="card-header"><div><h2>Agent catalog</h2><span class="subtle">Versions and autonomy modes are API-owned configuration.</span></div></div>${catalog.length ? `<div class="grid-2" style="padding:14px">${catalog.map((agent) => `<div class="card pad"><div class="section-header"><h3>${esc(agent.name)}</h3>${pill(agent.status, toneFor(agent.status))}</div><p class="subtle">${esc(agent.description || 'No description')}</p><div class="kpi-line"><span>Key</span><b>${esc(agent.key)}</b></div><div class="kpi-line"><span>Autonomy</span><b>${esc(agent.autonomy_mode)}</b></div><div class="kpi-line"><span>Version</span><b>v${esc(agent.version)}</b></div></div>`).join('')}</div>` : empty('No agents registered', 'The agent catalog endpoint returned no definitions.')}</section>${learning ? `<section class="card pad section"><div class="section-header"><h2>Learning signals</h2><span class="subtle">Advisory only</span></div><div class="grid-2 section"><div><h3>Outcomes</h3>${Object.entries(learning.outcomes || {}).map(([key, value]) => `<div class="kpi-line"><span>${esc(titleize(key))}</span><b>${esc(value)}</b></div>`).join('') || empty('No outcomes recorded')}</div><div><h3>Feedback</h3>${Object.entries(learning.agent_feedback || {}).map(([key, value]) => `<div class="kpi-line"><span>${esc(key)}</span><b>${esc(value.average)} / 5 · ${esc(value.count)} ratings</b></div>`).join('') || empty('No feedback recorded')}</div></div><div class="notice" style="margin-top:14px">${esc(learning.learning_policy)}</div></section>` : `<section class="card section">${empty('Learning data unavailable', 'The API did not return agent learning for this role or deployment.')}</section>`}`; }

async function analytics() { const [data, dashboard, locations, sourceData] = await Promise.all([api('/api/analytics'), api('/api/dashboard'), api('/api/analytics/locations'), api('/api/analytics/sources?days=30')]); const sources = sourceData.sources || []; document.getElementById('app').innerHTML = pageHead('Command / evidence', 'Analytics', 'Separate recovery proof from opportunity estimates, source economics, and observed influence.', `<button class="btn primary" data-action="spend-form">Add marketing spend</button>`) + `<div class="grid">${stat('Recovered', money(dashboard.actual_recovered), 'Attributable revenue')}${stat('Expected pipeline', money(dashboard.expected_value), 'Active opportunity signal')}${stat('Direct attribution', money(dashboard.directly_attributed), 'Hard revenue proof')}${stat('Assisted + influenced', money((dashboard.assisted_attributed || 0) + (dashboard.influenced_attributed || 0)), 'Observed contribution and association')}</div><div class="grid-2 section"><section class="card"><div class="card-header"><h2>Opportunity economics</h2></div>${data.by_type?.length ? `<div class="table-wrap"><table class="table"><thead><tr><th>Leak type</th><th>Count</th><th>Expected</th><th>Recovered</th></tr></thead><tbody>${data.by_type.map((item) => `<tr><td>${esc(titleize(item.type))}</td><td>${item.count}</td><td>${money(item.expected)}</td><td>${money(item.recovered)}</td></tr>`).join('')}</tbody></table></div>` : empty('No opportunity economics')}</section><section class="card pad"><div class="section-header"><h2>Location benchmark</h2><span class="subtle">Expected → recovered</span></div><div class="list section">${locations.length ? locations.map((item) => `<div><div class="kpi-line"><b>${esc(item.location)}</b><span>${money(item.recovered_amount)}</span></div><div class="progress"><span style="width:${item.expected_value ? Math.min(100, item.recovered_amount / item.expected_value * 100) : 0}%"></span></div><span class="subtle">${money(item.expected_value)} expected · ${item.opportunities} opportunities</span></div>`).join('') : empty('No location data')}</div></section></div><section class="card section"><div class="card-header"><div><h2>Lead-source economics</h2><span class="subtle">Last 30 days · explicit lineage only</span></div></div>${sources.length ? `<div class="table-wrap"><table class="table"><thead><tr><th>Source</th><th>Leads</th><th>Spend</th><th>Recovered</th><th>Recovery rate</th><th>ROAS</th></tr></thead><tbody>${sources.map((item) => `<tr><td><b>${esc(item.source)}</b></td><td>${item.leads}</td><td>${money(item.spend)}</td><td>${money(item.recovered)}</td><td>${item.recovery_rate == null ? '—' : percent(item.recovery_rate)}</td><td>${item.roas == null ? '—' : `${item.roas.toFixed(2)}x`}</td></tr>`).join('')}</tbody></table></div>` : empty('No source data', 'Explicit lead-source lineage and spend are required before economics can be shown.')}</section>`; }

async function setup() { const [onboarding, usage, keys, plan, features, users] = await Promise.all([api('/api/onboarding/status'), api('/api/tenant/usage'), api('/api/tenant/api-keys').catch(() => null), api('/api/billing/plan'), api('/api/features'), api('/api/users?limit=100').catch(() => null)]); document.getElementById('app').innerHTML = pageHead('Workspace / administration', 'Admin & setup', 'Get to first value, understand workspace readiness, and keep access, feature flags, usage, and secrets explicit.', `<button class="btn secondary" data-action="open-api-key">Create ingest key</button>`) + `<div class="tabs"><button class="tab active" data-action="setup-tab" data-tab="readiness">Readiness</button><button class="tab" data-action="setup-tab" data-tab="access">Access</button><button class="tab" data-action="setup-tab" data-tab="flags">Feature flags</button></div><div id="setup-panel"><div class="grid">${stat('Setup score', `${onboarding.score}%`, onboarding.next || 'Review your next setup step')}${stat('Plan', titleize(usage.plan || plan.plan_code), plan.subscription_status || 'Subscription state')}${stat('Monthly usage', `${usage.month_to_date_opportunities}/${usage.monthly_opportunity_limit}`, `${Math.round((usage.utilization || 0) * 100)}% utilized`)}${stat('Ingest keys', keys ? keys.length : '—', keys ? 'Tenant-scoped credentials' : 'Unavailable for this role')}</div><div class="grid-2 section"><section class="card pad"><div class="section-header"><h2>First-value checklist</h2><span class="subtle">${onboarding.steps?.filter((step) => step.complete).length || 0}/${onboarding.steps?.length || 0} complete</span></div><div class="list section">${onboarding.steps?.length ? onboarding.steps.map((step) => `<div class="kpi-line"><span>${esc(step.title)}</span>${pill(step.complete ? 'complete' : 'pending', step.complete ? 'good' : 'warn')}</div>`).join('') : empty('No checklist returned')}</div></section><section class="card pad"><div class="section-header"><h2>Usage & billing</h2><span class="subtle">Checkout availability is API-owned</span></div><div class="kpi-line"><span>Subscription</span><b>${esc(plan.subscription_status || '—')}</b></div><div class="kpi-line"><span>Billing checkout</span><b>${plan.billing_available ? 'Available' : 'Unavailable'}</b></div><p class="subtle" style="margin-top:14px">${esc(plan.message || 'Plan limits are enforced by the API.')}</p></section></div><section class="card pad section"><div class="section-header"><div><h2>Ingest API keys</h2><span class="subtle">Full secrets are returned once by the API.</span></div><button class="btn primary" data-action="open-api-key">Create key</button></div>${keys ? (keys.length ? `<div class="list section">${keys.map((key) => `<div class="kpi-line"><span><b>${esc(key.name)}</b> · ${esc(key.key_prefix)}… · ${date(key.created_at)}</span><span class="button-row">${pill(key.active ? 'active' : 'revoked', key.active ? 'good' : 'danger')}${key.active ? `<button class="btn danger" data-action="revoke-key" data-id="${esc(key.id)}">Revoke</button>` : ''}</span></div>`).join('')}</div>` : empty('No ingest keys', 'Create a key only when a trusted source is ready to send data.')) : empty('API keys unavailable', 'The current role or deployment cannot list tenant keys.')}</section></div>`; state.setupData = { onboarding, usage, keys, plan, features, users }; }

async function renderSetupTab(tab) { const data = state.setupData; document.querySelectorAll('[data-action="setup-tab"]').forEach((button) => button.classList.toggle('active', button.dataset.tab === tab)); const panel = document.getElementById('setup-panel'); if (!panel) return; if (tab === 'access') { panel.innerHTML = `<section class="card"><div class="card-header"><div><h2>Workspace access</h2><span class="subtle">Server-side RBAC controls all protected mutations.</span></div><span class="pill">Current role: ${esc(state.me.role)}</span></div>${data.users ? `<div class="table-wrap"><table class="table"><thead><tr><th>Email</th><th>Role</th><th>Status</th></tr></thead><tbody>${data.users.map((user) => `<tr><td>${esc(user.email)}</td><td>${pill(user.role)}</td><td>${pill(user.active ? 'active' : 'revoked', user.active ? 'good' : 'danger')}</td></tr>`).join('')}</tbody></table></div>` : empty('Team data unavailable', 'The current role cannot list workspace users.')}</section>`; } else if (tab === 'flags') { panel.innerHTML = `<section class="card pad"><div class="section-header"><div><h2>Feature flags</h2><span class="subtle">Read-only deployment capability signals from <code>/api/features</code>.</span></div></div><div class="grid-2 section">${Object.entries(data.features.features || {}).map(([key, enabled]) => `<div class="list-item"><div class="section-header"><strong>${esc(titleize(key))}</strong>${pill(enabled ? 'enabled' : 'disabled', enabled ? 'good' : 'warn')}</div><span class="subtle">This UI does not assume availability beyond the returned flag.</span></div>`).join('') || empty('No feature flags returned')}</div></section>`; } else { await setup(); } }

function searchModal() { const target = document.getElementById('overlay-root'); target.innerHTML = `<div class="overlay" data-action="close-search"></div><section class="search-modal"><div class="search-input">⌕ <input id="global-search" placeholder="Search customers, opportunities, reviews…" autofocus><button class="btn icon-btn" data-action="close-search">×</button></div><div class="search-results" id="search-results">${empty('Search your workspace', 'Enter at least two characters to query the existing search API.')}</div></section>`; const input = document.getElementById('global-search'); let timer; input.addEventListener('input', () => { clearTimeout(timer); timer = setTimeout(() => runSearch(input.value), 260); }); }
async function runSearch(query) { const results = document.getElementById('search-results'); if (!results) return; if (query.trim().length < 2) { results.innerHTML = empty('Search your workspace', 'Enter at least two characters to query the existing search API.'); return; } results.innerHTML = loading('Searching live workspace data…'); try { const response = await api(`/api/search?q=${encodeURIComponent(query.trim())}&limit=25`); const rows = response.results || []; results.innerHTML = rows.length ? rows.map((item) => `<button class="search-result" data-action="search-result" data-type="${esc(item.type || '')}" data-id="${esc(item.id || '')}"><b>${esc(item.title || item.name || item.email || item.id || 'Result')}</b><br><span class="subtle">${esc(item.type || 'record')} · ${esc(item.subtitle || item.description || item.email || '')}</span></button>`).join('') : empty('No matches', 'The search API returned no records for this query.'); } catch (error) { results.innerHTML = errorState(error); } }

async function scan() { try { const response = await api('/api/detect', { method: 'POST' }); toast(`Scan complete · ${response.created ?? 0} new opportunities`); navigate(state.page === 'overview' ? 'overview' : 'today'); } catch (error) { toast(error.message, 'error'); } }
async function makePlan(id) { const form = document.querySelector('form[data-form="recovery-action"]'); const channel = form?.elements.channel?.value || 'sms'; try { await api(`/api/opportunities/${encodeURIComponent(id)}/recovery-plan`, { method: 'POST', body: { channel } }); toast('Recovery plan created'); refreshOpportunity(); } catch (error) { toast(error.message, 'error'); } }
async function runAction(id, form) { try { const response = await api(`/api/opportunities/${encodeURIComponent(id)}/execute`, { method: 'POST', body: { channel: form.elements.channel.value, approval: true, idempotency_key: `ui-${id}-${Date.now()}`, message: form.elements.message.value } }); toast(response.note || 'Action recorded'); refreshOpportunity(); } catch (error) { toast(error.message, 'error'); } }
async function loadBrief(id) { const box = document.getElementById('brief-box'); if (!box) return; box.innerHTML = loading('Generating brief from stored evidence…'); try { const result = await api(`/api/opportunities/${encodeURIComponent(id)}/recovery-brief`); box.innerHTML = `<p><b>What happened:</b> ${esc(result.brief.what_happened)}</p><p><b>Why now:</b> ${esc(result.brief.why_now)}</p><p><b>Next step:</b> ${esc(result.brief.recommended_next_step)}</p><p class="subtle">${esc(result.brief.attribution_note)}</p>`; } catch (error) { box.innerHTML = errorState(error); } }
async function runAgents(id) { const box = document.getElementById('agent-trace'); if (box) box.innerHTML = loading('Running governed agent pipeline…'); try { const result = await api(`/api/opportunities/${encodeURIComponent(id)}/agents/run`, { method: 'POST' }); const runId = result.run_id || result.agent_run_id || result.id; if (runId) await loadAgentTrace(runId); else if (box) box.innerHTML = `<pre class="code-block">${esc(JSON.stringify(result, null, 2))}</pre>`; } catch (error) { if (box) box.innerHTML = errorState(error); } }
async function loadAgentTrace(runId) { const box = document.getElementById('agent-trace'); if (!box) return; box.innerHTML = loading('Loading agent trace…'); try { const data = await api(`/api/agent-runs/${encodeURIComponent(runId)}`); box.innerHTML = `<div class="grid-2"><div class="card pad"><div class="metric-label">Run status</div><div class="metric-value" style="font-size:23px">${esc(titleize(data.run.status))}</div><div class="metric-note">Pipeline ${esc(data.run.pipeline_version)} · started ${date(data.run.created_at, true)}</div></div><div class="card pad"><div class="metric-label">Trace nodes</div><div class="metric-value" style="font-size:23px">${data.agents.length}</div><div class="metric-note">${data.handoffs.length} handoffs · ${data.memories.length} memories</div></div></div><div class="list section">${data.agents.map((agent) => `<div class="list-item"><strong>${esc(agent.agent_definition_id)} · ${esc(titleize(agent.status))}</strong><span class="subtle">${date(agent.started_at, true)} → ${date(agent.completed_at, true)}</span><pre class="code-block" style="margin-top:9px">${esc(JSON.stringify(agent.output || {}, null, 2))}</pre></div>`).join('') || empty('No agent nodes returned')} </div><div class="card pad section"><h3>Run output</h3><pre class="code-block" style="margin-top:10px">${esc(JSON.stringify(data.run.output || {}, null, 2))}</pre></div>`; } catch (error) { box.innerHTML = errorState(error); } }

async function createPlaybook(form) { const body = { name: form.elements.name.value.trim(), description: form.elements.description.value.trim(), trigger_type: form.elements.trigger_type.value.trim(), conditions: { opportunity_types: form.elements.types.value.split(',').map((value) => value.trim()).filter(Boolean) }, steps: [{ action: 'investigate_context' }, { channel: form.elements.channel.value, action: 'prepare_message' }, { action: 'wait_and_detect_response' }, { action: 'attribute_outcome' }] }; try { await api('/api/playbooks', { method: 'POST', body }); toast('Draft automation created'); state.playbookBuilder = false; navigate('automation'); } catch (error) { toast(error.message, 'error'); } }
async function publishPlaybook(id) { try { await api(`/api/playbooks/${encodeURIComponent(id)}/publish`, { method: 'POST' }); toast('Automation published'); navigate('automation'); } catch (error) { toast(error.message, 'error'); } }
async function applyPlaybook(id) { renderDrawer(`<div class="drawer-head"><div><div class="eyebrow">Automation action</div><h2>Apply to an opportunity</h2><span class="subtle">Use an existing opportunity ID. The API will re-check conditions and approval gates.</span></div><button class="btn icon-btn" data-action="close-drawer">×</button></div><div class="drawer-body"><div class="notice warn">This creates or reuses an approval-gated plan. It does not send a customer message.</div><form data-form="apply-playbook" data-id="${esc(id)}" class="section"><div class="field"><label class="field-label">Opportunity ID</label><input name="opportunity_id" placeholder="opp_…" required></div><button class="btn primary" type="submit">Apply playbook</button></form></div>`); }
async function savePlaybookApplication(form) { try { const result = await api(`/api/playbooks/${encodeURIComponent(form.dataset.id)}/apply/${encodeURIComponent(form.elements.opportunity_id.value.trim())}`, { method: 'POST' }); toast(result.idempotent ? 'Existing plan reused' : 'Plan created and awaiting approval'); document.getElementById('overlay-root').innerHTML = ''; } catch (error) { toast(error.message, 'error'); } }
async function saveApiKey(form) { try { const response = await api('/api/tenant/api-keys', { method: 'POST', body: { name: form.elements.name.value.trim() } }); renderDrawer(`<div class="drawer-head"><div><div class="eyebrow">Secret created</div><h2>Copy this key now</h2></div><button class="btn icon-btn" data-action="close-drawer">×</button></div><div class="drawer-body"><div class="notice warn">This secret will not be shown again by the API. Store it in your secret manager before closing.</div><pre class="code-block" style="margin-top:14px">${esc(response.api_key)}</pre><button class="btn primary" style="margin-top:14px" data-action="close-drawer">I stored the key</button></div>`); } catch (error) { toast(error.message, 'error'); } }
async function revokeKey(id) { if (!window.confirm('Revoke this ingest key?')) return; try { await api(`/api/tenant/api-keys/${encodeURIComponent(id)}/revoke`, { method: 'POST' }); toast('API key revoked'); navigate('setup'); } catch (error) { toast(error.message, 'error'); } }
async function saveConnector(form, provider) { const credentials = {}; credentials[form.elements.credential_key.value.trim()] = form.elements.credential_value.value; try { await api(`/api/integrations/${encodeURIComponent(provider)}/configure`, { method: 'POST', body: { credentials, config: {} } }); toast('Credential stored securely'); await openConnector(provider); } catch (error) { toast(error.message, 'error'); } }
async function testConnector(provider) { try { const result = await api(`/api/integrations/${encodeURIComponent(provider)}/test`, { method: 'POST' }); toast(result.message || 'Connection verified'); await openConnector(provider); } catch (error) { toast(error.message, 'error'); } }
async function disconnectConnector(provider) { if (!window.confirm('Disconnect this integration and remove stored credentials?')) return; try { await api(`/api/integrations/${encodeURIComponent(provider)}/disconnect`, { method: 'POST' }); toast('Connector disconnected'); await openConnector(provider); } catch (error) { toast(error.message, 'error'); } }
async function oauthConnect(provider) { try { const result = await api(`/api/integrations/${encodeURIComponent(provider)}/oauth/start`, { method: 'POST' }); window.location.href = result.authorization_url; } catch (error) { toast(error.message, 'error'); } }

document.addEventListener('click', async (event) => {
  const target = event.target.closest('[data-action]'); if (!target) return; const action = target.dataset.action;
  if (action === 'auth-mode') return auth(target.dataset.mode);
  if (action === 'toggle-nav') { document.getElementById('sidebar')?.classList.toggle('open'); return; }
  if (action === 'navigate') return navigate(target.dataset.page);
  if (action === 'logout') return logout();
  if (action === 'open-search') { state.searchOpen = true; return searchModal(); }
  if (action === 'close-search') { document.getElementById('overlay-root').innerHTML = ''; return; }
  if (action === 'scan') return scan();
  if (action === 'retry') return navigate(target.dataset.page || state.page);
  if (action === 'open-opportunity') return openOpportunity(target.dataset.id);
  if (action === 'open-customer') return openCustomer(target.dataset.id);
  if (action === 'draft-review') return openReviewDraft(target.dataset.id);
  if (action === 'close-drawer') { document.getElementById('overlay-root').innerHTML = ''; state.drawer = null; return; }
  if (action === 'drawer-tab') { state.drawerTab = target.dataset.tab; if (state.drawer?.type === 'opportunity') renderOpportunityDrawer(); else if (state.drawer?.type === 'customer') renderCustomerDrawer(); return; }
  if (action === 'make-plan') return makePlan(target.dataset.id);
  if (action === 'dismiss-opportunity') { try { await api(`/api/opportunities/${encodeURIComponent(target.dataset.id)}/dismiss`, { method: 'POST' }); toast('Opportunity dismissed'); document.getElementById('overlay-root').innerHTML = ''; navigate(state.page); } catch (error) { toast(error.message, 'error'); } return; }
  if (action === 'load-brief') return loadBrief(target.dataset.id);
  if (action === 'run-agents') return runAgents(target.dataset.id);
  if (action === 'open-connector') return openConnector(target.dataset.id);
  if (action === 'connector-tab') { state.connectorTab = target.dataset.tab; return renderConnectorDrawer(); }
  if (action === 'oauth-connect') return oauthConnect(target.dataset.id);
  if (action === 'test-connector') return testConnector(target.dataset.id);
  if (action === 'disconnect-connector') return disconnectConnector(target.dataset.id);
  if (action === 'toggle-builder') { state.playbookBuilder = !state.playbookBuilder; return navigate('automation'); }
  if (action === 'publish-playbook') return publishPlaybook(target.dataset.id);
  if (action === 'apply-playbook') return applyPlaybook(target.dataset.id);
  if (action === 'open-api-key') return renderDrawer(`<div class="drawer-head"><div><div class="eyebrow">Workspace secret</div><h2>Create ingest key</h2><span class="subtle">Use only for a trusted machine-to-machine source.</span></div><button class="btn icon-btn" data-action="close-drawer">×</button></div><div class="drawer-body"><div class="notice warn">The full secret is returned once. The API enforces owner/admin permissions.</div><form data-form="api-key" class="section"><div class="field"><label class="field-label">Key name</label><input name="name" placeholder="production-ingest" required></div><button class="btn primary" type="submit">Create key</button></form></div>`);
  if (action === 'revoke-key') return revokeKey(target.dataset.id);
  if (action === 'setup-tab') return renderSetupTab(target.dataset.tab);
  if (action === 'runtime-refresh') { toast('Refreshing connector runtime…'); return navigate('connectors'); }
  if (action === 'approve-review') { try { await api(`/api/reviews/${encodeURIComponent(target.dataset.id)}/response-approve`, { method: 'POST' }); toast('Draft approved; provider send remains separate'); await openReviewDraft(target.dataset.id); } catch (error) { toast(error.message, 'error'); } }
  if (action === 'search-result') { document.getElementById('overlay-root').innerHTML = ''; if (target.dataset.type === 'customer') return openCustomer(target.dataset.id); if (target.dataset.type === 'opportunity') return openOpportunity(target.dataset.id); return toast('This result type has no detail workspace yet.'); }
});
document.addEventListener('submit', async (event) => {
  event.preventDefault(); const form = event.target; const data = Object.fromEntries(new FormData(form).entries());
  try {
    if (form.dataset.form === 'signin') { await api('/api/auth/login', { method: 'POST', body: data }); return boot(); }
    if (form.dataset.form === 'signup') { await api('/api/auth/register', { method: 'POST', body: data }); return boot(); }
    if (form.dataset.form === 'assign-opportunity') { await api(`/api/opportunities/${encodeURIComponent(form.dataset.id)}/assign`, { method: 'POST', body: { user_id: data.user_id || null } }); toast('Assignment saved'); return refreshOpportunity(); }
    if (form.dataset.form === 'recovery-action') return runAction(form.dataset.id, form);
    if (form.dataset.form === 'review-draft') { await api(`/api/reviews/${encodeURIComponent(form.dataset.id)}/response-draft`, { method: 'POST', body: { draft_text: data.draft_text } }); toast('Draft saved'); return openReviewDraft(form.dataset.id); }
    if (form.dataset.form === 'playbook') return createPlaybook(form);
    if (form.dataset.form === 'apply-playbook') return savePlaybookApplication(form);
    if (form.dataset.form === 'api-key') return saveApiKey(form);
    if (form.dataset.form === 'connector-config') return saveConnector(form, form.dataset.id);
  } catch (error) { toast(error.message, 'error'); }
});
document.addEventListener('keydown', (event) => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); searchModal(); } if (event.key === 'Escape') { const overlay = document.getElementById('overlay-root'); if (overlay) overlay.innerHTML = ''; } });
boot();
